write: {"content": "import csv

def normalize_country(value: str) -> str:
    v = value.strip().lower()
    if v in ('россия', 'ru', 'rus', 'russia'):
        return 'Россия'
    return value.strip()

def main():
    ru = 0
    foreign = 0
    try:
        with open('компоненты.csv', newline='', encoding='utf-8-sig') as f:
            reader = csv.reader(f, delimiter=';')
            header = next(reader, None)
            for row in reader:
                if len(row) < 3:
                    continue
                country = normalize_country(row[2])
                if country == 'Россия':
                    ru += 1
                elif country:
                    foreign += 1
    except FileNotFoundError:
        print('Файл компоненты.csv не найден')
        return

    total = ru + foreign
    percent = round(foreign / total * 100) if total else 0
    print(f'Россия — {ru}')
    print(f'Иностранные — {foreign}')
    print(f'Доля иностранных — {percent}%')

if __name__ == '__main__':
    main()
